use super::*;

/// 🎨️ Original attribute rows and samples transfer unchanged while replaced original indices close under actual receipts.
#[test]
fn original_mesh_tessellation_attribute_projection_keeps_exact_original_rows(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::{retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::controlled::ControlledRetirement};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧩️tessellation/🎟️owners.json")).unwrap();
    for copy in law["attributeProjection"]["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){for cut in[None,Some(0usize),Some(4),Some(15),Some(30)]{
        let(mut job,source)=observe(||{let mut mesh=super::tessellation_metadata_tests::authored_source(&law);for attribute in mesh.attributes.slot_values_mut(){attribute.indices=Some(serde_json::from_value(law["attributeProjection"]["sourceIndices"].clone()).unwrap());}let mut job=MeshTessellationJob::new(mesh);while !job.buffer_reservation_complete(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:job.next_buffer_capacity_byte_demand(0).unwrap(),maximum_release_bytes:0,maximum_depth:job.next_buffer_depth_demand().unwrap()};job.reserve_buffer_step(grant).unwrap();}while !job.metadata_capture_complete(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:job.next_metadata_depth_demand().unwrap()};job.capture_metadata_step(grant).unwrap();}while job.phase!=7{job.advance().unwrap();}for local in 0..3{let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:job.next_corner_copy_byte_demand(local).unwrap(),maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:job.next_corner_depth_demand(local).unwrap()};job.emit_corner_step(local,grant).unwrap();}job.face=job.mesh.face_count();job});
        let originals:Vec<_>=job.mesh.attributes.iter().map(|(key,attribute)|(key.clone(),key.as_ptr()as usize,attribute.values.as_ptr()as usize)).collect();let original=job.mesh.vertices.as_ptr();let(mut born,mut freed,mut turns)=(source.0,source.1,0);
        while !job.attribute_projection_complete(){if cut==Some(turns){let(_,heap)=observe(||job.cancel());assert_eq!(heap,(0,0));break;}
            let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:job.next_attribute_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:job.next_attribute_release_byte_demand().unwrap(),maximum_depth:job.next_attribute_depth_demand().unwrap()};
            for denied in [Some(RetainedCloneGrant {maximum_items:0,..grant}),(grant.maximum_capacity_bytes>0).then_some(RetainedCloneGrant {maximum_capacity_bytes:grant.maximum_capacity_bytes.saturating_sub(1),..grant}),(grant.maximum_release_bytes>0).then_some(RetainedCloneGrant {maximum_release_bytes:grant.maximum_release_bytes.saturating_sub(1),..grant}),(grant.maximum_depth>0).then_some(RetainedCloneGrant {maximum_depth:grant.maximum_depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observe(||job.project_attribute_step(denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(job.attribute_receipt.0,RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert_eq!(job.mesh.vertices.as_ptr(),original);}
            if job.attribute_stage==2&&job.attribute_cursor<job.attribute_domain_ids().unwrap().1.len(){for denied_copy in[0,1,3]{let(step,heap)=observe(||job.project_attribute_step(RetainedCloneGrant {maximum_copy_bytes:denied_copy,..grant}).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));}}
            let(step,heap)=observe(||job.project_attribute_step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(step.progress(),job.attribute_receipt.0);assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);assert_eq!(job.mesh.vertices.as_ptr(),original);
        }
        if cut.is_none(){assert!(job.mesh.attributes.is_empty());assert_eq!(job.output.as_ref().unwrap().attributes.len(),originals.len());for(key,key_address,values_address)in&originals{let(original_key,attribute)=job.output.as_ref().unwrap().attributes.get_key_value(key).unwrap();assert_eq!(original_key.as_ptr()as usize,*key_address);assert_eq!(attribute.values.as_ptr()as usize,*values_address);assert_eq!(attribute.indices.as_ref().unwrap(),&serde_json::from_value::<Vec<u32>>(law["attributeProjection"]["outputIndices"].clone()).unwrap());}}
        let(mut owner,handoff)=observe(||ControlledRetirement::new(job).unwrap_or_else(|_|panic!("original projection closure unsupported")));assert_eq!(handoff,(0,0));while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);}
        assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Mesh authored projection copy={copy} cut={cut:?} sameKeys=true sameValues=true actualOldIndicesClosure=true physical={freed} terminalDrop=0");
    }}
}
